&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Dragon &#233;sot&#233;rique astral&lt;div style=&quot;float:right;&quot;&gt;&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Dragon&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Dragon.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Ciel&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Ciel.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Extraplanaire&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Extraplanaire.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Bestiaire 5 p.94&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Dragon.html&quot; title=&quot;Dragon&quot;&gt;Dragon&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Extraplanaire.html&quot; title=&quot;Extraplanaire (sous-type)&quot;&gt;extraplanaire&lt;/a&gt;), N
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques de base&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;FP&lt;/b&gt; 5 ; &lt;b&gt;Taille&lt;/b&gt; P ; &lt;b&gt;DV&lt;/b&gt; 6d12
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 12 m
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Armure naturelle&lt;/b&gt; +4 ; &lt;b&gt;Souffle&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Defligne.html&quot; title=&quot;ligne&quot;&gt;ligne&lt;/a&gt;, 2d6 force
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 13, &lt;b&gt;Dex&lt;/b&gt; 16, &lt;b&gt;Con&lt;/b&gt; 12, &lt;b&gt;Int&lt;/b&gt; 15, &lt;b&gt;Sag&lt;/b&gt; 14, &lt;b&gt;Cha&lt;/b&gt; 10
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;&#201;cologie&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Environnement&lt;/b&gt; tous (plan Astral)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Organisation sociale&lt;/b&gt; solitaire
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Tr&#233;sor&lt;/b&gt; triple
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Capacit&#233;s sp&#233;ciales&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Changement de forme (Sur).&lt;/b&gt; Un dragon astral adulte ou plus &#226;g&#233; peut prendre la forme de n’importe quelle cr&#233;ature &lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;humano&#239;de&lt;/a&gt;, comme s’il utilisait &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphose.html&quot; title=&quot;M&#233;tamorphose&quot;&gt;m&#233;tamorphose&lt;/a&gt;&lt;/i&gt; et ce, trois fois par jour.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Ing&#233;rence psychique (Mag).&lt;/b&gt; Trois fois par jour, un dragon astral vieux ou plus &#226;g&#233; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barri&#232;re-Mentale-V.html&quot; title=&quot;Barri&#232;re mentale V&quot;&gt;barri&#232;re mentale V&lt;/a&gt;&lt;/i&gt; ou &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tour-De-Volont&#233;-De-Fer-Iii.html&quot; title=&quot;Tour de volont&#233; de fer III&quot;&gt;tour de volont&#233; de fer III&lt;/a&gt;&lt;/i&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; et en appliquant son &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; normal.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Magie psychique (Mag).&lt;/b&gt; Un dragon astral gagne les sorts psychiques suivants lorsqu’il atteint la cat&#233;gorie d’&#226;ge indiqu&#233;e : jeune – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;j&#224;-Vu.html&quot; title=&quot;D&#233;j&#224; vu&quot;&gt;d&#233;j&#224; vu&lt;/a&gt;&lt;/i&gt; (1 EP), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Projectile-T&#233;l&#233;kin&#233;tique.html&quot; title=&quot;Projectile t&#233;l&#233;kin&#233;tique&quot;&gt;projectile t&#233;l&#233;kin&#233;tique&lt;/a&gt;&lt;/i&gt; (0 EP) ; jeune adulte – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Analyse-Daura.html&quot; title=&quot;Analyse d&amp;#39;aura&quot;&gt;analyse d’aura&lt;/a&gt;&lt;/i&gt; (3 EP), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;go&#251;t.html&quot; title=&quot;D&#233;go&#251;t&quot;&gt;d&#233;go&#251;t&lt;/a&gt;&lt;/i&gt; (2 EP), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Insinuation-Du-&#199;a-I.html&quot; title=&quot;Insinuation du &#231;a I&quot;&gt;insinuation du &#231;a I&lt;/a&gt;&lt;/i&gt; (2 EP) ; &#226;ge m&#251;r - &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Perception-Des-Pens&#233;es.html&quot; title=&quot;Perception des pens&#233;es&quot;&gt;perception des pens&#233;es&lt;/a&gt;&lt;/i&gt; (4 EP) ; tr&#232;s vieux – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Possession-Spirituelle-(Sort).html&quot; title=&quot;Possession spirituelle&quot;&gt;possession spirituelle&lt;/a&gt;&lt;/i&gt; (5 EP) ; dracosire – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Broyage-Psychique-Iv.html&quot; title=&quot;Broyage psychique IV&quot;&gt;broyage psychique IV&lt;/a&gt;&lt;/i&gt; (8 EP).
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Souffle d&#233;stabilisant (Sur).&lt;/b&gt; Une fois par jour, quand un dragon astral v&#233;n&#233;rable ou plus &#226;g&#233; utilise son &lt;a class=&quot;pagelink&quot; href=&quot;Souffle-(Capacit&#233;).html&quot; title=&quot;Souffle (Sur)&quot;&gt;souffle&lt;/a&gt;, les cr&#233;atures qui ratent leur jet de sauvegarde sont &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Chancelant.html&quot; title=&quot;Chancelant&quot;&gt;chancelantes&lt;/a&gt; pendant 2d4 rounds.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Voyage &#224; la vitesse de la pens&#233;e (Sur).&lt;/b&gt; Tant qu’il se trouve dans le plan Astral, un grand dracosire astral peut se t&#233;l&#233;porter par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt;, o&#249; il le souhaite et quelle que soit la distance qui le s&#233;pare de sa destination.
&lt;/div&gt;&lt;br /&gt;&lt;/div&gt;&lt;/td&gt;
&lt;td&gt;&lt;div&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 0 0; margin: 0 0 4px 8px&quot;&gt;
&lt;table CLASS=&quot;tablo autoalt&quot;&gt;&lt;caption&gt;Variantes de dragon astral&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Nom&lt;/td&gt;&lt;td&gt;FP&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Jeune-Dragon-Astral.html&quot; title=&quot;Dragon &#233;sot&#233;rique, Jeune dragon astral&quot;&gt;Jeune dragon astral&lt;/a&gt;&lt;/td&gt;&lt;td&gt;9&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Astral-Adulte.html&quot; title=&quot;Dragon &#233;sot&#233;rique, Dragon astral adulte&quot;&gt;Dragon astral adulte&lt;/a&gt;&lt;/td&gt;&lt;td&gt;13&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Astral-V&#233;n&#233;rable.html&quot; title=&quot;Dragon &#233;sot&#233;rique, Dragon astral v&#233;n&#233;rable&quot;&gt;Dragon astral v&#233;n&#233;rable&lt;/a&gt;&lt;/td&gt;&lt;td&gt;18&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;ul style=&quot;margin: 0 0 -10 0;margin-top: 6px;margin-bottom: 12px;&quot;&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Voir la description des &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-&#201;sot&#233;rique.html&quot; title=&quot;Les dragons &#233;sot&#233;riques&quot;&gt;dragons &#233;sot&#233;riques&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/li&gt;&lt;/ul&gt;&lt;i&gt;Ce majestueux dragon semble scintiller sous l’effet d’une multitude de
pens&#233;es astrales tourbillonnantes.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;R&#233;serv&#233;s et hautains, ces dragons sillonnent le plan Astral pour en apprendre toujours plus sur les secrets &#233;sot&#233;riques de cette dimension. Ils chassent pour se nourrir et utilisent la magie psychique pour affronter leurs semblables.&lt;br /&gt;&lt;br /&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo toutgauche&quot;&gt;&lt;caption&gt;Tableau des gains de capacit&#233;s&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Cat&#233;gorie d&#39;&#226;ge &lt;/td&gt;&lt;td&gt;Capacit&#233;s sp&#233;ciales&lt;/td&gt;&lt;td&gt;NLS&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Dragonnet&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aura-Dintellect-Statique-(Capacit&#233;).html&quot; title=&quot;Aura d’intellect statique (Sur)&quot;&gt;aura d&#39;intellect statique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Tr&#232;s jeune&lt;/td&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Linvisibilit&#233;.html&quot; title=&quot;D&#233;tection de l&amp;#39;invisibilit&#233;&quot;&gt;d&#233;tection de l&#39;invisibilit&#233;&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Jeune&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Magie-Psychique-(Capacit&#233;).html&quot; title=&quot;Magie psychique (Mag)&quot;&gt;magie psychique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Adolescent&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;silience-Psychique-(Capacit&#233;).html&quot; title=&quot;R&#233;silience psychique (Ext)&quot;&gt;r&#233;silience psychique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Jeune adulte&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Magie-Psychique-(Capacit&#233;).html&quot; title=&quot;Magie psychique (Mag)&quot;&gt;magie psychique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 5/magie&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Adulte&lt;/td&gt;&lt;td&gt;changement de forme, &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sence-Terrifiante-(Capacit&#233;).html&quot; title=&quot;Pr&#233;sence terrifiante&quot;&gt;pr&#233;sence terrifiante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;7&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&#194;ge m&#251;r&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Magie-Psychique-(Capacit&#233;).html&quot; title=&quot;Magie psychique (Mag)&quot;&gt;magie psychique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 10/magie&lt;/td&gt;&lt;td&gt;9&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Vieux&lt;/td&gt;&lt;td&gt;ing&#233;rence psychique&lt;/td&gt;&lt;td&gt;11&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Tr&#232;s vieux&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Magie-Psychique-(Capacit&#233;).html&quot; title=&quot;Magie psychique (Mag)&quot;&gt;magie psychique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 15/magie&lt;/td&gt;&lt;td&gt;13&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;V&#233;n&#233;rable&lt;/td&gt;&lt;td&gt;souffle d&#233;stabilisant&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Dracosire&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Magie-Psychique-(Capacit&#233;).html&quot; title=&quot;Magie psychique (Mag)&quot;&gt;magie psychique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 20/magie&lt;/td&gt;&lt;td&gt;17&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Grand dracosire&lt;/td&gt;&lt;td&gt;voyage &#224; la vitesse de la pens&#233;e&lt;/td&gt;&lt;td&gt;19&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/center&gt;
&lt;/div&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
